module.exports = async function(data) {
  // Directus request operation puts the parsed JSON under `.data`.
  const res = data.generate_article && data.generate_article.data;
  if (!res || !res.ok || !res.article) {
    const err = res && res.error ? res.error : 'unknown error from /api/articles/generate';
    throw new Error(`Article generation failed: ${err}`);
  }

  const a = res.article;
  const hero = a.heroImage || {};

  // camelCase → snake_case, matching the `articles` collection fields
  // used by the rest of the codebase (see lib/articles.ts).
  // Author arrives as the full object — we keep only the slug so Directus
  // resolves the M2O against the `authors` collection. If the slug doesn't
  // exist yet, the item-create step will 4xx — seed the four canonical
  // authors (baguette, sofia-mendoza, diego-ramirez, ana-vargas) once.
  return {
    payload: {
      slug:                a.slug,
      title:               a.title,
      short:               a.short,
      excerpt:             a.excerpt,
      category:            a.category,
      status:              'draft',
      published_at:        a.publishedAt,
      read_minutes:        a.readMinutes,
      hero_image_alt:      hero.alt || '',
      hero_image_caption:  hero.caption || null,
      body:                a.body || [],
      body_eli5:           a.bodyEli5 || null,
      author:              (a.author && a.author.slug) || 'baguette'
    },
    usage: res.usage || null
  };
};
